package main

import "fmt"

func main() {
	fmt.Println("=== Inisialisasi Map ===")
	// Membuat map dengan key string dan value int
	inventory := make(map[string]int)

	// Tambah / Ubah data
	inventory["laptop"] = 10
	inventory["mouse"] = 50
	inventory["keyboard"] = 25

	fmt.Println("Inventory awal:", inventory)

	// Menghapus data
	delete(inventory, "mouse")
	fmt.Println("Setelah dihapus:", inventory)

	fmt.Println("\n=== Memeriksa Key (The 'ok' Idiom) ===")
	// Mencoba mengambil barang yang tidak ada
	qty, ok := inventory["monitor"]
	if ok {
		fmt.Println("Monitor ditemukan, qty:", qty)
	} else {
		fmt.Println("Monitor tidak ditemukan di inventory!")
	}

	fmt.Println("\n=== For Range pada Map ===")
	// Urutan iterasi map bersifat ACAK secara default di Go!
	for key, val := range inventory {
		fmt.Printf("Item: %s, Qty: %d\n", key, val)
	}
}
